1	import { EFFORT_LEVELS, type Effort, effectiveModels, loadConfig } from "./config.ts";
2	import { trace } from "./diagnostics.ts";
3	import { DEFAULT_MAX_TOKENS, type ChatMessage, type DeltaChannel, type Usage, chat } from "./groq.ts";
4	import { logger } from "./logger.ts";
5	import { costFromBreakdown, costFromUsage } from "./pricing.ts";
6	import { buildSystemPrompt } from "./prompts.ts";
7	import { formatToolResults, parseToolCalls, stripToolBlocks } from "./protocol.ts";
8	import { type ApprovalRequest, type TodoItem, buildTools, executeTool, isSafeBash } from "./tools.ts";
9	
10	export interface AgentCallbacks {
11	  onDelta?: (text: string, channel: DeltaChannel) => void;
12	  onAssistantText?: (text: string) => void;
13	  onToolStart?: (tool: string, args: Record<string, unknown>) => void;
14	  onToolEnd?: (tool: string, status: "ok" | "error", output: string) => void;
15	  onApproval?: (req: ApprovalRequest) => Promise<boolean>;
16	  onUsage?: (usage: Usage, cost: number) => void;
17	  onNotice?: (text: string) => void;
18	  onTodos?: (todos: TodoItem[]) => void;
19	}
20	
21	export interface AgentState {
22	  messages: ChatMessage[];
23	  totalUsage: Usage;
24	  lastPromptTokens: number;
25	}
26	
27	export function newAgentState(): AgentState {
28	  return {
29	    messages: [],
30	    totalUsage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
31	    lastPromptTokens: 0,
32	  };
33	}
34	
35	function addUsage(state: AgentState, usage: Usage): void {
36	  state.totalUsage.prompt_tokens += usage.prompt_tokens;
37	  state.totalUsage.completion_tokens += usage.completion_tokens;
38	  state.totalUsage.total_tokens += usage.total_tokens;
39	  state.lastPromptTokens = usage.prompt_tokens;
40	}
41	
42	const ACTION_CLAIM_RE =
43	  /\b(?:I (?:created|wrote|ran|executed|made|added|updated|edited|installed|saved|built|recorded)|(?:has|have) been (?:created|written|executed|run|made|updated|edited|saved|built|recorded|noted|remembered)|was (?:created|written|executed|run|made|updated|edited|saved|built|recorded)|successfully (?:created|wrote|written|ran|executed|updated|built|saved)|script has|file now contains|the output (?:is|was)|tests?\s+(?:now\s+)?(?:all\s+)?pass|all tests pass)/i;
44	
45	function claimsAction(text: string): boolean {
46	  return ACTION_CLAIM_RE.test(text);
47	}
48	
49	const SUCCESS_CLAIM_RE =
50	  /\b(?:all tests pass|tests?\s+(?:now\s+)?(?:all\s+)?pass(?:es|ed)?|task is (?:now )?(?:complete|done)|successfully|works as (?:expected|intended|requested)|is (?:now )?(?:complete|fixed|working|resolved))\b/i;
51	
52	function claimsSuccess(text: string): boolean {
53	  return SUCCESS_CLAIM_RE.test(text);
54	}
55	
56	const GUESSED_CONTENT_RE =
57	  /\b(?:illustrative|typical contents?|likely (?:contains?|stored|located|holds?|lives|includes?)|presumably|probably (?:contains?|holds?|has|includes?)|based on (?:naming|common) (?:conventions?|patterns?)|might look (?:like|similar)|would typically|\(presumed?\b|common patterns\))/i;
58	
59	function looksGuessed(text: string): boolean {
60	  return GUESSED_CONTENT_RE.test(text);
61	}
62	
63	function approvalSummary(tool: string, args: Record<string, unknown>): ApprovalRequest {
64	  if (tool === "bash") {
65	    const cmd = String(args.command ?? "");
66	    return { tool, summary: "Run shell command", detail: cmd };
67	  }
68	  if (tool === "write_file") {
69	    const content = String(args.content ?? "");
70	    const preview = content.split("\n").slice(0, 12).join("\n");
71	    return {
72	      tool,
73	      summary: `Write ${args.path} (${content.split("\n").length} lines)`,
74	      detail: preview + (content.split("\n").length > 12 ? "\n…" : ""),
75	    };
76	  }
77	  if (tool === "edit_file") {
78	    return {
79	      tool,
80	      summary: `Edit ${args.path}`,
81	      detail: `- ${String(args.old_string ?? "").slice(0, 400)}\n+ ${String(args.new_string ?? "").slice(0, 400)}`,
82	    };
83	  }
84	  return { tool, summary: `Run ${tool}`, detail: JSON.stringify(args).slice(0, 400) };
85	}
86	
87	export async function runSubagent(task: string, signal?: AbortSignal): Promise<string> {
88	  const tools = buildTools({});
89	  const subTools = new Map([...tools].filter(([, t]) => t.subagentSafe));
90	  const system = buildSystemPrompt({ tools: subTools, effort: "low", subagent: true });
91	  const messages: ChatMessage[] = [
92	    { role: "system", content: system },
93	    { role: "user", content: task },
94	  ];
95	  const { subagent: subagentModel } = effectiveModels();
96	  const executed = new Set<string>();
97	  let emptyNudged = false;
98	  for (let i = 0; i < 8; i++) {
99	    const res = await chat(messages, { model: subagentModel, signal, enabledTools: [], maxTokens: DEFAULT_MAX_TOKENS });
100	    const key = (c: { tool: string; args: Record<string, unknown> }) =>
101	      c.tool + JSON.stringify(c.args);
102	    const contentCalls = parseToolCalls(res.content);
103	    const reasoningCalls = res.reasoning ? parseToolCalls(res.reasoning) : [];
104	    const contentKeys = new Set(contentCalls.map(key));
105	    const calls = [
106	      ...contentCalls,
107	      ...reasoningCalls.filter((c) => !contentKeys.has(key(c)) && !executed.has(key(c))),
108	    ];
109	    for (const c of calls) executed.add(key(c));
110	    messages.push({ role: "assistant", content: res.content });
111	    if (calls.length === 0) {
112	      const visible = stripToolBlocks(res.content);
113	      if (visible) return visible;
114	      const reasoningText = res.reasoning ? stripToolBlocks(res.reasoning) : "";
115	      if (!emptyNudged) {
116	        emptyNudged = true;
117	        messages.push({
118	          role: "user",
119	          content:
120	            "[continue] Your last message was empty. Emit the next tool block, or state your findings in plain text.",
121	        });
122	        continue;
123	      }
124	      return reasoningText || "(subagent returned no answer)";
125	    }
126	    const results = [];
127	    for (const call of calls) {
128	      if (call.tool === "bash" && !isSafeBash(String(call.args.command ?? ""))) {
129	        results.push({
130	          tool: call.tool,
131	          status: "error" as const,
132	          output: "subagents may only run read-only shell commands",
133	        });
134	        continue;
135	      }
136	      const r = await executeTool(subTools, call.tool, call.args);
137	      results.push({ tool: call.tool, ...r });
138	    }
139	    messages.push({ role: "user", content: formatToolResults(results) });
140	  }
141	  return "(subagent ran out of tool rounds without a final answer)";
142	}
143	
144	/** Review whether the goal was achieved. Returns { done, reason }. */
145	export async function reviewGoal(
146	  state: AgentState,
147	  goal: string,
148	): Promise<{ done: boolean; reason: string }> {
149	  const transcript = state.messages
150	    .filter((m) => m.role !== "system")
151	    .map((m) => `[${m.role}]\n${m.content.slice(0, 3000)}`)
152	    .join("\n\n")
153	    .slice(-30_000);
154	
155	  const res = await chat(
156	    [
157	      {
158	        role: "system",
159	        content: `You are a goal reviewer. Your job: read the conversation transcript and decide whether the original goal was achieved.
160	
161	Key principle: match your judgment to the goal's nature. A conversational question ("how can you help?", "what is X?") is met by a relevant, substantive answer — tools are not required. A task goal ("fix the bug", "create a file") requires actual tool results.
162	
163	Rules:
164	- If the goal was conversational (a question, greeting, or request for info) and the agent gave a relevant, helpful response, answer YES.
165	- If the goal required concrete action (file edits, commands, code changes) and every part was accomplished with real tool results, answer YES.
166	- If the goal required action but any part was skipped, failed, or only described but not executed, answer NO.
167	- If the agent hit an iteration limit or got stuck on a task goal, answer NO.
168	
169	Respond with exactly one line: YES: <brief reason> or NO: <brief reason>.`,
170	      },
171	      {
172	        role: "user",
173	        content: `Goal: ${goal}\n\nTranscript:\n${transcript || "(empty)"}`,
174	      },
175	    ],
176	    { model: effectiveModels().subagent, maxTokens: 512 },
177	  );
178	
179	  const text = res.content.trim();
180	  if (/^\s*YES[:\s]/i.test(text) || /^\s*YES$/i.test(text)) {
181	    return { done: true, reason: text.replace(/^\s*YES:?\s*/i, "") };
182	  }
183	  return { done: false, reason: text.replace(/^\s*NO:?\s*/i, "") || "goal not fully achieved" };
184	}
185	
186	export async function runTurn(
187	  state: AgentState,
188	  userMessage: string,
189	  effort: Effort,
190	  cb: AgentCallbacks,
191	  signal?: AbortSignal,
192	): Promise<void> {
193	  const config = loadConfig();
194	  const { agent: agentModel } = effectiveModels();
195	
196	  // Auto-mode: quick pre-check with llama-3.1-8b-instant to decide if
197	  // write/edit/bash tools are actually needed for this request.
198	  let autoModeReadOnly = false;
199	  if (config.auto) {
200	    try {
201	      const pre = await chat(
202	        [
203	          { role: "system", content: "You decide whether a user's request requires creating/editing files or running commands to satisfy it. If the user is just asking a question, asking for analysis, or requesting an explanation — something that can be fully answered in plain text — answer NO. If they explicitly asked to create, write, edit, build, install, deploy, or run something that would change files or execute commands, answer YES. Answer only YES or NO." },
204	          { role: "user", content: userMessage.slice(0, 2000) },
205	        ],
206	        { model: "llama-3.1-8b-instant", maxTokens: 8, temperature: 0 },
207	      );
208	      if (/^\s*no\b/i.test(pre.content.trim())) {
209	        autoModeReadOnly = true;
210	        cb.onNotice?.("auto-mode: request looks like a question — answering in-chat (no file writes or commands)");
211	      }
212	    } catch (e) {
213	      // If the pre-check fails, allow tools (fail-open).
214	      trace("auto.precheck_failed", { error: String(e) });
215	    }
216	  }
217	
218	  const tools = buildTools({
219	    onSubagent: (task) => runSubagent(task, signal),
220	    onTodos: cb.onTodos ?? (() => {}),
221	  });
222	
223	  // If auto-mode decided no tool use is needed, filter out write/edit/bash.
224	  const effectiveTools = autoModeReadOnly
225	    ? new Map([...tools].filter(([, t]) => !t.needsApproval))
226	    : tools;
227	
228	  // If tools were filtered, also restrict the agent's system prompt.
229	  const system = buildSystemPrompt({ tools: effectiveTools, effort });
230	  const maxIterations = EFFORT_LEVELS[effort].maxIterations;
231	
232	  state.messages.push({ role: "user", content: userMessage });
233	  trace("turn.user", { chars: userMessage.length, effort, autoMode: config.auto });
234	  logger.info("turn.start", { effort, history: state.messages.length, autoMode: config.auto });
235	
236	  const turnExecuted = new Set<string>();
237	  let realityNudges = 0;
238	  let verifyNudges = 0;
239	  let failureNudges = 0;
240	  let emptyNudges = 0;
241	  let guessNudges = 0;
242	  let lastModifyRound = -1;
243	  let lastVerifyRound = -1;
244	  let lastBashFailed = false;
245	
246	  for (let round = 0; round < maxIterations; round++) {
247	    if (signal?.aborted) throw new Error("aborted");
248	    const res = await chat([{ role: "system", content: system }, ...state.messages], {
249	      model: agentModel,
250	      signal,
251	      onDelta: cb.onDelta,
252	      enabledTools: [],
253	      maxTokens: DEFAULT_MAX_TOKENS,
254	    });
255	    addUsage(state, res.usage);
256	    cb.onUsage?.(res.usage, res.breakdown ? costFromBreakdown(res.breakdown) : costFromUsage(res.usage));
257	
258	    // compound surfaces a reasoning channel; the model sometimes "performs"
259	    // tool calls there and never repeats them in content. Salvage those, but
260	    // only once per turn — it re-emits the same calls every round.
261	    const key = (c: { tool: string; args: Record<string, unknown> }) =>
262	      c.tool + JSON.stringify(c.args);
263	    const contentCalls = parseToolCalls(res.content);
264	    const reasoningCalls = res.reasoning ? parseToolCalls(res.reasoning) : [];
265	    const contentKeys = new Set(contentCalls.map(key));
266	    const novelReasoningCalls = reasoningCalls.filter(
267	      (c) => !contentKeys.has(key(c)) && !turnExecuted.has(key(c)),
268	    );
269	    const calls = [...contentCalls, ...novelReasoningCalls];
270	    for (const c of calls) turnExecuted.add(key(c));
271	
272	    const visible = stripToolBlocks(res.content);
273	    trace("turn.assistant", { round, chars: res.content.length, tool_calls: calls.length });
274	    state.messages.push({ role: "assistant", content: res.content });
275	
276	    if (calls.length === 0) {
277	      // Stall guard: an empty reply (everything stuck in the reasoning
278	      // channel) is not an answer. Push the model to continue.
279	      if (!visible && emptyNudges < 2) {
280	        emptyNudges++;
281	        state.messages.push({
282	          role: "user",
283	          content:
284	            "[continue] Your last message was empty. Continue the task: emit the next tool block, or — if you are genuinely done — state your final answer in plain text.",
285	        });
286	        trace("turn.empty_nudge", { round });
287	        logger.warn("turn.empty_nudge", { round });
288	        continue;
289	      }
290	      // Fabrication guard: a "final" answer claiming actions when zero tools
291	      // ran this turn is invented. Bounce it back (and don't show it).
292	      if (turnExecuted.size === 0 && realityNudges < 2 && claimsAction(res.content)) {
293	        realityNudges++;
294	        state.messages.push({
295	          role: "user",
296	          content:
297	            "[reality check] You executed ZERO tools this turn, so nothing you described actually happened — no files exist, no commands ran. Perform the task for real now using tool blocks (<glint:tool> ... </glint:tool>), one step at a time, and wait for each result.",
298	        });
299	        trace("turn.reality_nudge", { round });
300	        logger.warn("turn.reality_nudge", { round });
301	        continue;
302	      }
303	      // Verification guard: files were modified but nothing was run afterward
304	      // to prove the change works. Ask for proof.
305	      if (lastModifyRound !== -1 && lastVerifyRound < lastModifyRound && verifyNudges < 2) {
306	        verifyNudges++;
307	        state.messages.push({
308	          role: "user",
309	          content:
310	            "[verification check] You modified files but ran nothing afterward to verify the change. Run the relevant test/build/command now and only then conclude — if it fails, keep fixing. If you genuinely cannot fix it, say so honestly instead of claiming success.",
311	        });
312	        trace("turn.verify_nudge", { round });
313	        logger.warn("turn.verify_nudge", { round });
314	        continue;
315	      }
316	      // Assumption guard: "illustrative"/"typical contents" answers are
317	      // fabricated file descriptions. Demand reads of the real files.
318	      if (guessNudges < 2 && looksGuessed(res.content)) {
319	        guessNudges++;
320	        state.messages.push({
321	          role: "user",
322	          content:
323	            "[assumption check] Your answer contains GUESSED content (words like 'typical', 'likely', 'illustrative', 'presumably'). That is fabrication. Read the actual files with read_file/ls/grep — every file, field, and behavior you describe must come from a real tool result in this conversation. Rewrite the answer from evidence only, and drop anything you cannot verify.",
324	        });
325	        trace("turn.guess_nudge", { round });
326	        logger.warn("turn.guess_nudge", { round });
327	        continue;
328	      }
329	      // Failure-denial guard: the most recent command FAILED but the final
330	      // answer claims success anyway.
331	      if (lastBashFailed && failureNudges < 2 && claimsSuccess(res.content)) {
332	        failureNudges++;
333	        state.messages.push({
334	          role: "user",
335	          content:
336	            "[failure check] Your most recent command FAILED — the task is NOT done. Either fix the problem and prove it with a passing run, or state plainly that it is unresolved and why. Do not claim success.",
337	        });
338	        trace("turn.failure_nudge", { round });
339	        logger.warn("turn.failure_nudge", { round });
340	        continue;
341	      }
342	      if (visible) cb.onAssistantText?.(visible);
343	      if (lastBashFailed && claimsSuccess(res.content)) {
344	        cb.onNotice?.(
345	          "⚠ the last command this turn failed, but the summary above claims success — verify before trusting it",
346	        );
347	      }
348	      logger.info("turn.done", { rounds: round + 1 });
349	      return;
350	    }
351	
352	    // Calls pending: show brief narration only. Long mid-round text is a
353	    // draft answer the model will re-state once results land — hold it, along
354	    // with premature "I did X" claims.
355	    if (visible && visible.length <= 240 && !claimsAction(visible)) cb.onAssistantText?.(visible);
356	
357	    const results: Array<{ tool: string; status: "ok" | "error"; output: string }> = [];
358	    for (const call of calls) {
359	      if (signal?.aborted) throw new Error("aborted");
360	      const spec = tools.get(call.tool);
361	      let approved = true;
362	      if (spec?.needsApproval && !config.yolo) {
363	        const autoSafe = call.tool === "bash" && isSafeBash(String(call.args.command ?? ""));
364	        if (!autoSafe && cb.onApproval) {
365	          approved = await cb.onApproval(approvalSummary(call.tool, call.args));
366	          trace("tool.approval", { tool: call.tool, approved });
367	        }
368	      }
369	      if (!approved) {
370	        results.push({ tool: call.tool, status: "error", output: "user denied this action" });
371	        cb.onToolEnd?.(call.tool, "error", "denied by user");
372	        continue;
373	      }
374	      cb.onToolStart?.(call.tool, call.args);
375	      const result = await executeTool(effectiveTools, call.tool, call.args);
376	      results.push({ tool: call.tool, ...result });
377	      cb.onToolEnd?.(call.tool, result.status, result.output);
378	      if (result.status === "ok" && (call.tool === "write_file" || call.tool === "edit_file")) {
379	        lastModifyRound = round;
380	      }
381	      if (call.tool === "bash") {
382	        lastBashFailed = result.status === "error";
383	        if (result.status === "ok") lastVerifyRound = round;
384	      }
385	    }
386	    state.messages.push({ role: "user", content: formatToolResults(results) });
387	  }
388	
389	  cb.onNotice?.(
390	    `Reached the ${effort}-effort limit of ${maxIterations} tool rounds. Say "continue" to keep going, or raise /effort.`,
391	  );
392	  logger.warn("turn.max_iterations", { maxIterations });
393	  trace("turn.max_iterations", { maxIterations });
394	}
