47	const SAFE_BASH_PREFIXES = [
48	  "ls", "cat ", "head ", "tail ", "grep ", "rg ", "find ", "pwd", "wc ", "which ",
49	  "echo ", "git status", "git log", "git diff", "git show", "git branch", "file ",
50	  "stat ", "du ", "df", "ps ", "env", "date", "uname", "tree", "sort ", "uniq ",
