63	async function runBash(command: string, timeoutS: number): Promise<string> {
64	  const proc = Bun.spawn(["bash", "-c", command], {
65	    cwd: process.cwd(),
66	    stdout: "pipe",
67	    stderr: "pipe",
68	    env: { ...process.env, GIT_PAGER: "cat", PAGER: "cat" },
69	  });
70	  const timer = setTimeout(() => proc.kill(), timeoutS * 1000);
71	  const [out, err, code] = await Promise.all([
72	    new Response(proc.stdout).text(),
73	    new Response(proc.stderr).text(),
74	    proc.exited,
75	  ]);
76	  clearTimeout(timer);
77	  let result = out;
78	  if (err.trim()) result += (result ? "\n" : "") + `[stderr]\n${err}`;
79	  if (code !== 0) {
80	    result += `\n[exit code: ${code}]`;
81	    throw new Error(cap(result.trim()));
82	  }
83	  return cap(result.trim() || "(no output)");
84	}
