23	export function loadSkill(name: string): Skill | null {
24	  const path = join(DIRS.skills, `${name}.md`);
25	  if (!existsSync(path)) return null;
26	  const raw = readFileSync(path, "utf8");
27	  const fm = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
28	  let description = "";
29	  let body = raw;
30	  if (fm) {
31	    const descLine = fm[1].split("\n").find((l) => l.startsWith("description:"));
32	    description = descLine ? descLine.slice("description:".length).trim() : "";
33	    body = fm[2].trim();
34	  }
35	  return { name, description, body };
