9	export async function compactHistory(state: AgentState): Promise<string> {
10	  if (state.messages.length < 4) return "Nothing to compact yet.";
11	  const keepTail = state.messages.slice(-2);
12	  const toSummarize = state.messages.slice(0, -2);
13	  const transcript = toSummarize
14	    .map((m) => `[${m.role}]\n${m.content.slice(0, 4000)}`)
15	    .join("\n\n");
16	
17	  const res = await chat(
18	    [
19	      {
20	        role: "system",
21	        content:
22	          "Summarize this agent conversation for context compaction. Preserve: the user's goals, decisions made, files created/modified with their paths, key facts discovered, current task state, and anything still unfinished. Be dense and factual. Output only the summary.",
23	      },
24	      { role: "user", content: transcript.slice(0, 100_000) },
25	    ],
26	    { model: SUBAGENT_MODEL, maxTokens: 2048 },
27	  );
28	
29	  const before = state.messages.length;
30	  state.messages = [
31	    {
32	      role: "user",
33	      content: `[Context was compacted. Summary of the conversation so far:]\n\n${res.content}`,
34	    },
35	    { role: "assistant", content: "Understood — continuing from that summary." },
36	    ...keepTail,
37	  ];
38	  state.lastPromptTokens = 0;
39	  logger.info("compact.done", { before, after: state.messages.length });
40	  trace("compact", { before, after: state.messages.length });
41	  return `Compacted ${before} messages → ${state.messages.length}.`;
42	}
